function brothPoint(cx, cy, rx, ry, u, v) { return [cx + u * rx, cy + v * ry]; }

// ================= SCENE =================
function drawBackground(t, flick, mx, my) {
  const g = ctx.createLinearGradient(0, 0, 0, H);
  g.addColorStop(0, "#04060b");
  g.addColorStop(0.5, "#070c13");
  g.addColorStop(1, "#0a0d12");
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);

  // faint cool top light
  let cg = ctx.createRadialGradient(W * 0.5 + mx * 30, H * -0.1, 10, W * 0.5 + mx * 30, H * -0.1, H * 0.9);
  cg.addColorStop(0, "rgba(90,130,170,0.10)");
  cg.addColorStop(1, "rgba(90,130,170,0)");
  ctx.fillStyle = cg;
  ctx.fillRect(0, 0, W, H);

  // warm hearth glow behind bowl
  const gx = CX + mx * S * 0.03, gy = CY + R * 0.55;
  const gr = Math.max(W, H) * 0.55;
  const wg = ctx.createRadialGradient(gx, gy, 10, gx, gy, gr);
  const pulse = 0.30 + flick * 0.07;
  wg.addColorStop(0, "rgba(255,138,42," + pulse.toFixed(3) + ")");
  wg.addColorStop(0.25, "rgba(180,80,25," + (pulse * 0.55).toFixed(3) + ")");
  wg.addColorStop(0.6, "rgba(60,25,10,0.10)");
  wg.addColorStop(1, "rgba(0,0,0,0)");
  ctx.fillStyle = wg;
  ctx.fillRect(0, 0, W, H);

  // table surface: subtle warm band
  const tg = ctx.createLinearGradient(0, CY + R * 0.4, 0, H);
  tg.addColorStop(0, "rgba(255,150,60,0.06)");
  tg.addColorStop(0.3, "rgba(20,16,12,0.35)");
  tg.addColorStop(1, "rgba(0,0,0,0.55)");
  ctx.fillStyle = tg;
  ctx.fillRect(0, CY + R * 0.4, W, H - (CY + R * 0.4));
}

function drawDustBack(t, mx, my) {
  for (const d of dust) {
    const tw = 0.5 + 0.5 * Math.sin(t * 0.8 + d.ph);
    const x = d.x * W - mx * 18 * d.r * 0.4;
    const y = ((d.y - t * d.sp * 0.25) % 1 + 1) % 1 * H - my * 10;
    const a = d.a * 0.35 * (0.4 + 0.6 * tw);
    ctx.beginPath();
    ctx.arc(x, y, d.r, 0, 6.2832);
    ctx.fillStyle = d.warm ? "rgba(255,180,110," + a.toFixed(3) + ")" : "rgba(160,190,220," + a.toFixed(3) + ")";
    ctx.fill();
  }
}

function drawShadowAndGlow(cx, cy, flick) {
  // floor shadow
  ctx.save();
  ctx.globalAlpha = 0.55;
  ellipse(cx, cy + R * 0.86, R * 1.18, R * 0.22);
  const sg = ctx.createRadialGradient(cx, cy + R * 0.86, 5, cx, cy + R * 0.86, R * 1.18);
  sg.addColorStop(0, "rgba(0,0,0,0.85)");
  sg.addColorStop(0.6, "rgba(0,0,0,0.45)");
  sg.addColorStop(1, "rgba(0,0,0,0)");
  ctx.fillStyle = sg;
  ctx.fill();
  ctx.restore();
  // warm bounce under bowl
  ctx.save();
  ctx.globalCompositeOperation = "screen";
  ellipse(cx, cy + R * 0.72, R * 0.95, R * 0.16);
  const bg2 = ctx.createRadialGradient(cx, cy + R * 0.72, 4, cx, cy + R * 0.72, R * 0.95);
  bg2.addColorStop(0, "rgba(255,150,60," + (0.20 + flick * 0.06).toFixed(3) + ")");
  bg2.addColorStop(1, "rgba(255,150,60,0)");
  ctx.fillStyle = bg2;
  ctx.fill();
  ctx.restore();
  // table reflection streak
  ctx.save();
  ctx.globalAlpha = 0.10 + flick * 0.02;
  const rw = R * 0.5;
  const rg = ctx.createLinearGradient(0, cy + R * 0.9, 0, H);
  rg.addColorStop(0, "rgba(255,170,90,0.5)");
  rg.addColorStop(1, "rgba(255,170,90,0)");
  ctx.fillStyle = rg;
  ctx.beginPath();
  ctx.moveTo(cx - rw, cy + R * 0.9);
  ctx.lineTo(cx + rw, cy + R * 0.9);
  ctx.lineTo(cx + rw * 1.8, H);
  ctx.lineTo(cx - rw * 1.8, H);
  ctx.closePath();
  ctx.fill();
  ctx.restore();
}

