function drawBowl(cx, cy, t, mx, flick) {
  const depth = R * 0.78;
  const botY = cy + depth;
  // body
  ctx.save();
  ctx.beginPath();
  ctx.moveTo(cx - R, cy);
  ctx.bezierCurveTo(cx - R * 0.98, cy + depth * 0.55, cx - R * 0.45, botY, cx, botY);
  ctx.bezierCurveTo(cx + R * 0.45, botY, cx + R * 0.98, cy + depth * 0.55, cx + R, cy);
  ctx.ellipse(cx, cy, R, R * 0.365, 0, 0, Math.PI, true);
  ctx.closePath();
  const body = ctx.createLinearGradient(cx - R, cy, cx + R, botY);
  body.addColorStop(0, "#232c38");
  body.addColorStop(0.12, "#141a23");
  body.addColorStop(0.45, "#080b10");
  body.addColorStop(1, "#020304");
  ctx.fillStyle = body;
  ctx.fill();

  // warm rim bounce on lower body
  ctx.save();
  ctx.clip();
  const warm = ctx.createRadialGradient(cx + mx * R * 0.3, botY - R * 0.1, 5, cx + mx * R * 0.3, botY - R * 0.1, R * 1.2);
  warm.addColorStop(0, "rgba(255,140,50," + (0.22 + flick * 0.05).toFixed(3) + ")");
  warm.addColorStop(0.5, "rgba(120,50,15,0.08)");
  warm.addColorStop(1, "rgba(0,0,0,0)");
  ctx.fillStyle = warm;
  ctx.fillRect(cx - R, cy, R * 2, depth + R * 0.4);
  // cool edge light left
  const cool = ctx.createLinearGradient(cx - R, 0, cx - R * 0.3, 0);
  cool.addColorStop(0, "rgba(140,180,220,0.20)");
  cool.addColorStop(1, "rgba(140,180,220,0)");
  ctx.fillStyle = cool;
  ctx.fillRect(cx - R, cy, R * 0.7, depth + R * 0.4);
  ctx.restore();

  // foot
  ellipse(cx, botY + R * 0.015, R * 0.34, R * 0.085);
  ctx.fillStyle = "#05070a";
  ctx.fill();
  ellipse(cx, botY, R * 0.30, R * 0.075);
  const foot = ctx.createLinearGradient(0, botY - R * 0.07, 0, botY + R * 0.07);
  foot.addColorStop(0, "#2b3442");
  foot.addColorStop(0.4, "#0d1117");
  foot.addColorStop(1, "#000000");
  ctx.fillStyle = foot;
  ctx.fill();

  // glossy side streak (moves with mouse = interactive sheen)
  ctx.save();
  ctx.globalAlpha = 0.16;
  ctx.translate(cx - R * 0.52 + mx * R * 0.12, cy + depth * 0.45);
  ctx.rotate(0.22);
  ellipse(0, 0, R * 0.075, depth * 0.32);
  const sheen = ctx.createLinearGradient(0, -depth * 0.3, 0, depth * 0.3);
  sheen.addColorStop(0, "rgba(255,255,255,0)");
  sheen.addColorStop(0.5, "rgba(255,235,200,0.9)");
  sheen.addColorStop(1, "rgba(255,255,255,0)");
  ctx.fillStyle = sheen;
  ctx.fill();
  ctx.restore();
  ctx.restore();

  // rim: thick ceramic lip
  ctx.save();
  ctx.lineWidth = Math.max(8, R * 0.085);
  ctx.strokeStyle = "#1c232e";
  ctx.beginPath();
  ctx.ellipse(cx, cy, R * 0.965, R * 0.35, 0, 0, Math.PI * 2);
  ctx.stroke();
  // warm front lip light
  ctx.lineWidth = Math.max(2, R * 0.022);
  ctx.strokeStyle = "rgba(255,190,120,0.55)";
  ctx.beginPath();
  ctx.ellipse(cx, cy, R * 0.965, R * 0.35, 0, Math.PI * 0.15, Math.PI * 0.85);
  ctx.stroke();
  // cool back lip
  ctx.strokeStyle = "rgba(150,190,230,0.28)";
  ctx.beginPath();
  ctx.ellipse(cx, cy, R * 0.965, R * 0.35, 0, Math.PI * 1.12, Math.PI * 1.88);
  ctx.stroke();
  // inner shadow groove
  ctx.lineWidth = Math.max(3, R * 0.03);
  ctx.strokeStyle = "rgba(0,0,0,0.65)";
  ctx.beginPath();
  ctx.ellipse(cx, cy, R * 0.885, R * 0.318, 0, 0, Math.PI * 2);
  ctx.stroke();
  ctx.restore();
}

function drawBroth(cx, cy, t, mx, my, flick) {
  const bx = cx, by = cy - R * 0.015;
  const rx = R * 0.855, ry = R * 0.855 * 0.362;
  ctx.save();
