function noodleStrand(x, y, s, rot, t, seed, col) {
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(rot);
  ctx.strokeStyle = col;
  ctx.lineCap = "round";
  const wob = Math.sin(t * 1.1 + seed) * s * 0.02;
  ctx.lineWidth = s * 0.055;
  ctx.beginPath();
  ctx.moveTo(-s * 0.55, 0);
  ctx.bezierCurveTo(-s * 0.3, -s * 0.22 + wob, -s * 0.05, s * 0.20 + wob, s * 0.2, -s * 0.05 + wob);
  ctx.bezierCurveTo(s * 0.35, -s * 0.18, s * 0.45, s * 0.10, s * 0.58, 0);
  ctx.stroke();
  ctx.strokeStyle = "rgba(255,246,214,0.85)";
  ctx.lineWidth = s * 0.018;
  ctx.beginPath();
  ctx.moveTo(-s * 0.52, -s * 0.03);
  ctx.bezierCurveTo(-s * 0.28, -s * 0.24 + wob, -s * 0.03, s * 0.17 + wob, s * 0.22, -s * 0.07 + wob);
  ctx.stroke();
  ctx.restore();
}

function drawNoodles(b, t) {
  const cxp = b.bx - b.rx * 0.18, cyp = b.by + b.ry * 0.28;
  const s = R * 0.52;
  const cols = ["#c99a4e", "#e0b96a", "#d4a556", "#e8c67e", "#c08a3e", "#f0d18c", "#d9ad5c"];
  for (let i = 0; i < 9; i++) {
    const a = (i / 9) * Math.PI - Math.PI / 2 + Math.sin(i * 7.3) * 0.3;
    const rr = 0.28 + (i % 4) * 0.16;
    noodleStrand(cxp + Math.cos(a) * s * rr * 0.7, cyp + Math.sin(a) * s * rr * 0.30,
      s * (0.72 - (i % 3) * 0.08), Math.sin(i * 3.1) * 0.5 + (i % 2 ? 0.25 : -0.2), t, i * 1.7, cols[i % cols.length]);
  }
  // glossy broth glaze over noodles
  ctx.save();
  ctx.globalAlpha = 0.18;
  ctx.strokeStyle = "#fff0c8";
  ctx.lineWidth = R * 0.012;
  ctx.lineCap = "round";
  ctx.beginPath();
  ctx.ellipse(cxp, cyp - R * 0.02, s * 0.42, s * 0.15, -0.15, Math.PI * 1.15, Math.PI * 1.75);
  ctx.stroke();
  ctx.restore();
}

