function drawSteam(cx, cy, t, dt, mx) {
  ctx.save();
  ctx.globalCompositeOperation = "screen";
  const baseY = cy - R * 0.28;
  const riseH = S * 0.72;
  for (const s of steam) {
    s.life += dt * s.speed * (reduced ? 0 : 1);
    if (s.life >= 1) {
      s.life -= 1;
      s.lane = Math.random() * 2 - 1;
      s.swirl = Math.random() * Math.PI * 2;
    }
    const l = s.life;
    const sway = Math.sin(l * 5.0 + s.swirl + t * s.swirlSpd * 0.6) * R * 0.16 * s.wob;
    const bend = wind * l * l * 1.6 + mx * R * 0.35 * l * l;
    const x = cx + s.lane * R * 0.55 * (1 - l * 0.4) + sway + bend;
    const y = baseY - l * riseH;
    const rad = (R * 0.16 + l * R * 0.42) * s.girth;
    const a = Math.sin(l * Math.PI);
    const alpha = a * 0.13;
    if (alpha <= 0.003) continue;
    const g = ctx.createRadialGradient(x, y, 1, x, y, rad);
    g.addColorStop(0, "rgba(255,244,230," + alpha.toFixed(3) + ")");
    g.addColorStop(0.5, "rgba(230,220,210," + (alpha * 0.55).toFixed(3) + ")");
    g.addColorStop(1, "rgba(220,210,200,0)");
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(x, y, rad, 0, 6.2832);
    ctx.fill();
    // warm core near bowl
    if (l < 0.35) {
      const wa = (1 - l / 0.35) * 0.10 * a;
      const wg = ctx.createRadialGradient(x, y + rad * 0.3, 1, x, y + rad * 0.3, rad * 0.7);
      wg.addColorStop(0, "rgba(255,170,90," + wa.toFixed(3) + ")");
      wg.addColorStop(1, "rgba(255,170,90,0)");
      ctx.fillStyle = wg;
      ctx.beginPath();
      ctx.arc(x, y + rad * 0.3, rad * 0.7, 0, 6.2832);
      ctx.fill();
    }
  }
  ctx.restore();
}

function drawFrontDust(t, mx) {
  for (const d of dust) {
    if (!d.warm && (d.ph % 2 < 1)) continue;
    const tw = 0.5 + 0.5 * Math.sin(t * 1.4 + d.ph * 2);
    const drift = Math.sin(t * 0.4 + d.ph) * 12;
    const x = d.x * W + drift - mx * 30 * (d.r * 0.3);
    const y = ((d.y - t * d.sp * 0.5) % 1 + 1) % 1 * H;
    const nearBowl = Math.hypot(x - CX, y - CY) < R * 1.6;
    const a = d.a * 0.5 * (0.35 + 0.65 * tw) * (nearBowl ? 1.4 : 0.7);
    if (a < 0.02) continue;
    ctx.beginPath();
    ctx.arc(x, y, d.r * (nearBowl ? 1.3 : 1), 0, 6.2832);
    ctx.fillStyle = "rgba(255,190,120," + Math.min(0.6, a).toFixed(3) + ")";
    ctx.fill();
  }
}

function drawVignetteAndGrain(t, flick) {
  const vg = ctx.createRadialGradient(CX, CY - R * 0.1, S * 0.2, CX, CY, Math.max(W, H) * 0.75);
  vg.addColorStop(0, "rgba(0,0,0,0)");
  vg.addColorStop(0.55, "rgba(0,0,0,0.18)");
  vg.addColorStop(1, "rgba(0,0,0,0.72)");
  ctx.fillStyle = vg;
  ctx.fillRect(0, 0, W, H);
  // subtle top glow flicker wash
  ctx.save();
  ctx.globalCompositeOperation = "screen";
  ctx.globalAlpha = 0.05 + flick * 0.015;
  const fg = ctx.createRadialGradient(CX, CY - R * 0.4, 10, CX, CY - R * 0.4, R * 2.2);
  fg.addColorStop(0, "rgba(255,170,100,0.6)");
  fg.addColorStop(1, "rgba(255,170,100,0)");
  ctx.fillStyle = fg;
  ctx.fillRect(CX - R * 2.2, CY - R * 2.6, R * 4.4, R * 3.4);
  ctx.restore();
  // film grain
  ctx.save();
  ctx.globalAlpha = 0.055;
  const ox = reduced ? 0 : ((t * 47) % 128) | 0;
  const oy = reduced ? 0 : ((t * 31) % 128) | 0;
  for (let y = -oy; y < H; y += 128) {
    for (let x = -ox; x < W; x += 128) {
      ctx.drawImage(grainTile, x, y);
    }
  }
  ctx.restore();
}

