function render(t, dt) {
  // smooth pointer + wind (skipped under reduced motion)
  let mx = 0, my = 0;
  if (!reduced) {
    const k = 1 - Math.pow(0.001, dt);
    const prevX = ptr.x, prevY = ptr.y;
    ptr.x += (ptr.tx - ptr.x) * Math.min(1, k * 1.2 + 0.02);
    ptr.y += (ptr.ty - ptr.y) * Math.min(1, k * 1.2 + 0.02);
    ptr.vx = (ptr.x - prevX) / Math.max(dt, 0.001);
    ptr.vy = (ptr.y - ptr.y) / 1;
    mx = ptr.x; my = ptr.y;
    const windTarget = clamp(ptr.x * 22 + ptr.vx * 14, -60, 60);
    wind += (windTarget - wind) * Math.min(1, dt * 2.2);
  }
  const fl = flicker(t);
  const breathe = reduced ? 0 : Math.sin(t * 0.6) * S * 0.004;
  const cx = CX + mx * S * 0.018;
  const cy = CY + my * S * 0.012 + breathe;

