  drawNori(b, t);
  drawNoodles(b, t);
  drawBokChoy(b, t);
  drawMushroom(b, t);
  drawTofu(b, t);
  drawSmallToppings(b, t, mx);
  drawSteam(cx, cy, t, dt, mx);
  drawFrontDust(t, mx);
  drawVignetteAndGrain(t, fl);
}

function drawStatic() {
  wind = 0;
  render(1.35, 0.016);
}

resize();
if (reduced) {
  drawStatic();
} else {
  let last = performance.now();
  const t0 = last;
  // seed steam across lifetimes so first frame is already full
  render(1.35, 0.016);
  const frame = (now) => {
    let dt = (now - last) / 1000;
    last = now;
    if (!(dt > 0 && dt < 0.1)) dt = 0.016;
    const t = (now - t0) / 1000 + 1.35;
    render(t, dt);
    requestAnimationFrame(frame);
  };
  requestAnimationFrame(frame);
}
})();
