const fs = require("fs");
const path = "<WORKSPACE>/meta/muse-spark-1.3/xhigh/index.html";
const html = fs.readFileSync(path, "utf8");

// zero-external-asset + purity checks
const checks = [];
checks.push(["no http(s) refs", !/https?:\/\//.test(html)]);
checks.push(["no src=/href=/link/img", !/\ssrc=|\shref=|<link|<img/i.test(html)]);
checks.push(["no @import/url(/fetch", !/@import|url\(|fetch\(|XMLHttpRequest/.test(html)]);
const bodyText = html.split("<body>")[1].split("</body>")[0].replace(/<script[\s\S]*<\/script>/g, "").replace(/<canvas[\s\S]*?<\/canvas>/g, "").trim();
checks.push(["body has no visible text/UI nodes", bodyText === "" || /^<canvas[^>]*>$/.test(bodyText.trim())]);

function makeGradient() { return { addColorStop() {} }; }
function makeCtx2D() {
  return {
    canvas: null,
    fillStyle: "", strokeStyle: "", lineWidth: 1, globalAlpha: 1,
    globalCompositeOperation: "source-over", shadowColor: "", shadowBlur: 0, lineCap: "",
    setTransform() {}, fillRect() {}, fill() {}, stroke() {}, beginPath() {},
    ellipse() {}, arc() {}, moveTo() {}, lineTo() {}, bezierCurveTo() {},
    quadraticCurveTo() {}, closePath() {}, save() {}, restore() {}, clip() {},
    translate() {}, rotate() {}, drawImage() {}, roundRect() {}, arcTo() {},
    createLinearGradient: makeGradient, createRadialGradient: makeGradient,
    createImageData(w, h) { return { width: w, height: h, data: new Uint8ClampedArray(w * h * 4) }; },
    putImageData() {}, getImageData(w, h) { return { data: [] }; },
  };
}
function runOnce(reducedMotion, label) {
  let rafQueue = [];
  let listeners = {};
  const tileCtx = makeCtx2D();
  const mainCtx = makeCtx2D();
  const fakeCanvas = {
    width: 0, height: 0,
    getContext() { mainCtx.canvas = fakeCanvas; return mainCtx; },
  };
  const sandboxWindow = {
    innerWidth: 1280, innerHeight: 800, devicePixelRatio: 2,
    matchMedia: () => ({ matches: reducedMotion, addEventListener() {} }),
    addEventListener(t, fn) { (listeners[t] = listeners[t] || []).push(fn); },
    performance: { now: () => 1000 },
  };
  const sandboxDocument = {
    getElementById: () => fakeCanvas,
    createElement: () => ({ width: 0, height: 0, getContext: () => tileCtx }),
    addEventListener() {},
  };
  const m = html.match(/<script>([\s\S]*)<\/script>/);
  if (!m) throw new Error("no inline script found");
  const src = m[1];
  const fn = new Function("window", "document", "performance", "requestAnimationFrame",
    "cancelAnimationFrame", "CanvasRenderingContext2D",
    `"use strict"; const self=window; const top=window; const parent=window;` +
    `var innerWidth=window.innerWidth, innerHeight=window.innerHeight, devicePixelRatio=window.devicePixelRatio;` +
    `var matchMedia=window.matchMedia.bind(window); var addEventListener=window.addEventListener.bind(window);` +
    src);
  let rafCalls = 0;
  const raf = (cb) => { rafCalls++; rafQueue.push(cb); return rafCalls; };
  global.window = sandboxWindow;
  fn(sandboxWindow, sandboxDocument, sandboxWindow.performance, raf, () => {}, undefined);
  // fire resize listener like a viewport change
  if (listeners.resize) listeners.resize.forEach((f) => f());
  // exercise interactivity: pointermove then frames
  if (listeners.pointermove) listeners.pointermove.forEach((f) => f({ clientX: 900, clientY: 300 }));
  let frames = 0;
  let now = 1016;
  while (rafQueue.length && frames < 5) {
    const q = rafQueue; rafQueue = [];
    for (const cb of q) { cb(now); frames++; now += 16; }
    if (reducedMotion) break;
  }
  console.log(`${label}: rafCallbacks=${rafCalls} framesExecuted=${frames} canvas=${fakeCanvas.width}x${fakeCanvas.height}`);
  if (fakeCanvas.width <= 0 || fakeCanvas.height <= 0) throw new Error(label + ": canvas not sized");
  if (!reducedMotion && frames < 1) throw new Error(label + ": no rAF frame ran");
  if (reducedMotion && rafCalls !== 0) throw new Error(label + ": reduced-motion must not schedule rAF");
  return { rafCalls, frames };
}

for (const [name, ok] of checks) console.log((ok ? "PASS" : "FAIL") + " - " + name);
if (checks.some((c) => !c[1])) process.exitCode = 1;
runOnce(false, "motion");
runOnce(true, "reduced-motion");
console.log("smoke OK");
